#### StarRating.razor (interactive component)
Create `/tmp/sv-d7bfb3e112f845368d8c6e3f3af85aa1/RecipeShare/Components/StarRating.razor`:

```razor
@using RecipeShare.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="star-rating">
    <div class="star-buttons">
        @for (int i = 1; i <= 5; i++)
        {
            int star = i;
            <button class="star-btn @(IsHighlighted(star) ? "active" : "")"
                    @onclick="() => Rate(star)"
                    @onmouseover="() => hoverStar = star"
                    @onmouseout="() => hoverStar = 0"
                    title="Rate @star star@(star > 1 ? "s" : "")">
                @(IsHighlighted(star) ? "★" : "☆")
            </button>
        }
    </div>
    @if (submitted)
    {
        <span class="rating-feedback">Thanks for rating!</span>
    }
    @if (recipe is not null)
    {
        <span class="rating-info">
            @recipe.AverageRating.ToString("F1") avg · @recipe.Ratings.Count ratings
        </span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private RecipeShare.Models.Recipe? recipe;
    private int hoverStar;
    private bool submitted;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(RecipeId);
    }

    private bool IsHighlighted(int star) =>
        star <= (hoverStar > 0 ? hoverStar : (submitted ? (int)Math.Round(recipe?.AverageRating ?? 0) : 0));

    private void Rate(int star)
    {
        RecipeService.AddRating(RecipeId, star);
        recipe = RecipeService.GetById(RecipeId);
        submitted = true;
        hoverStar = 0;
    }
}
```

This component has `@rendermode InteractiveServer` — it's the interactive island in an otherwise static page.

#### SubmitRecipe.razor (interactive page)
Create `/tmp/sv-d7bfb3e112f845368d8c6e3f3af85aa1/RecipeShare/Components/Pages/SubmitRecipe.razor`:

```razor
@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<nav class="breadcrumb">
    <a href="/">Home</a> &rsaquo; <span>Submit Recipe</span>
</nav>

<h1>📤 Submit a Recipe</h1>

@if (successMessage is not null)
{
    <div class="alert-success">
        <p>@successMessage</p>
        <a href="/recipe/@submittedId">View your recipe</a>
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" class="recipe-form" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary />

        <div class="form-group">
            <label for="title">Recipe Title</label>
            <InputText id="title" @bind-Value="model.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => model.Title" />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <InputSelect id="category" @bind-Value="model.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
            <ValidationMessage For="() => model.Category" />
        </div>

        <div class="form-group">
            <label for="description">Description</label>
            <InputTextArea id="description" @bind-Value="model.Description" placeholder="A brief description of your recipe" />
            <ValidationMessage For="() => model.Description" />
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="model.IngredientsText" rows="6"
                           placeholder="1 cup flour&#10;2 eggs&#10;1/2 cup sugar" />
            <ValidationMessage For="() => model.IngredientsText" />
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="model.StepsText" rows="6"
                           placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
            <ValidationMessage For="() => model.StepsText" />
        </div>

        <button type="submit" class="btn-submit">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel model = new();
    private string? successMessage;
    private int submittedId;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Description = model.Description,
            Ingredients = model.IngredientsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = model.StepsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        };
        RecipeService.AddRecipe(recipe);
        submittedId = recipe.Id;
        successMessage = $"\"{recipe.Title}\" has been submitted!";
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        [System.ComponentModel.DataAnnotations.StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
        public string Title { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required.")]
        public string Category { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Description is required.")]
        [System.ComponentModel.DataAnnotations.StringLength(500, ErrorMessage = "Description must be 500 characters or fewer.")]
        public string Description { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please add at least one ingredient.")]
        public string IngredientsText { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please add at least one step.")]
        public string StepsText { get; set; } = "";
    }
}
```

