```razor
@using RecipeShare.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="star-rating">
    <div class="star-buttons">
        @for (int i = 1; i <= 5; i++)
        {
            int star = i;
            <button class="star-btn @(IsHighlighted(star) ? "active" : "")"
                    @onclick="() => Rate(star)"
                    @onmouseover="() => hoverStar = star"
                    @onmouseout="() => hoverStar = 0"
                    title="Rate @star star@(star > 1 ? "s" : "")">
                @(IsHighlighted(star) ? "★" : "☆")
            </button>
        }
    </div>
    @if (submitted)
    {
        <span class="rating-feedback">Thanks for rating!</span>
    }
    @if (recipe is not null)
    {
        <span class="rating-info">
            @recipe.AverageRating.ToString("F1") avg · @recipe.Ratings.Count ratings
        </span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private RecipeShare.Models.Recipe? recipe;
    private int hoverStar;
    private bool submitted;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(RecipeId);
    }

    private bool IsHighlighted(int star) =>
        star <= (hoverStar > 0 ? hoverStar : (submitted ? (int)Math.Round(recipe?.AverageRating ?? 0) : 0));

    private void Rate(int star)
    {
        RecipeService.AddRating(RecipeId, star);
        recipe = RecipeService.GetById(RecipeId);
        submitted = true;
        hoverStar = 0;
    }
}
```

