namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Description { get; set; } = "";
    public List<string> Ingredients { get; set; } = new();
    public List<string> Steps { get; set; } = new();
    public List<int> Ratings { get; set; } = new();
    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1,
            Title = "Classic Margherita Pizza",
            Category = "Italian",
            Description = "A simple and delicious pizza with fresh mozzarella and basil.",
            Ingredients = new() { "Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt" },
            Steps = new()
            {
                "Preheat oven to 475°F (245°C) with a pizza stone if available.",
                "Stretch dough into a 12-inch round on a floured surface.",
                "Spread crushed tomatoes evenly, leaving a 1-inch border.",
                "Tear mozzarella into pieces and distribute over the sauce.",
                "Bake for 10-12 minutes until crust is golden and cheese is bubbly.",
                "Top with fresh basil leaves and a drizzle of olive oil."
            },
            Ratings = new() { 5, 4, 5, 4, 5 }
        },
        new Recipe
        {
            Id = 2,
            Title = "Chicken Tikka Masala",
            Category = "Indian",
            Description = "Tender chicken pieces in a creamy, spiced tomato sauce.",
            Ingredients = new() { "Chicken breast", "Yogurt", "Garam masala", "Tomato puree", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric" },
            Steps = new()
            {
                "Marinate chicken in yogurt, garam masala, and salt for at least 1 hour.",
                "Grill or pan-sear chicken until charred and cooked through.",
                "Sauté onion, garlic, and ginger until soft.",
                "Add spices and tomato puree, simmer for 15 minutes.",
                "Stir in cream and add the cooked chicken.",
                "Simmer for 10 more minutes. Serve with rice or naan."
            },
            Ratings = new() { 5, 5, 4, 5 }
        },
        new Recipe
        {
            Id = 3,
            Title = "Beef Tacos",
            Category = "Mexican",
            Description = "Flavorful seasoned beef in warm tortillas with fresh toppings.",
            Ingredients = new() { "Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Lime" },
            Steps = new()
            {
                "Brown ground beef in a skillet over medium-high heat.",
                "Add taco seasoning and water, simmer until thickened.",
                "Warm tortillas in a dry pan or microwave.",
                "Fill tortillas with seasoned beef.",
                "Top with shredded lettuce, diced tomato, cheese, and sour cream.",
                "Squeeze fresh lime juice over tacos before serving."
            },
            Ratings = new() { 4, 4, 5, 3, 4 }
        },
        new Recipe
        {
            Id = 4,
            Title = "Pad Thai",
            Category = "Thai",
            Description = "Stir-fried rice noodles with shrimp, peanuts, and tangy sauce.",
            Ingredients = new() { "Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Sugar", "Lime" },
            Steps = new()
            {
                "Soak rice noodles in warm water for 30 minutes, then drain.",
                "Mix tamarind paste, fish sauce, and sugar for the sauce.",
                "Stir-fry shrimp until pink, push to the side, scramble eggs.",
                "Add noodles and sauce, toss everything together.",
                "Add bean sprouts and green onions, cook 1 minute.",
                "Serve topped with crushed peanuts and lime wedges."
            },
            Ratings = new() { 5, 4, 5 }
        },
        new Recipe
        {
            Id = 5,
            Title = "Spaghetti Carbonara",
            Category = "Italian",
            Description = "Creamy pasta with pancetta, egg, and Parmesan — no cream needed.",
            Ingredients = new() { "Spaghetti", "Pancetta", "Eggs", "Parmesan cheese", "Black pepper", "Salt" },
            Steps = new()
            {
                "Cook spaghetti in salted boiling water until al dente.",
                "Crisp pancetta in a large skillet.",
                "Whisk eggs and grated Parmesan together.",
                "Drain pasta, reserving 1 cup of pasta water.",
                "Toss hot pasta with pancetta, then remove from heat.",
                "Pour egg mixture over pasta, toss quickly, adding pasta water to reach desired creaminess."
            },
            Ratings = new() { 5, 5, 5, 4, 4, 5 }
        },
        new Recipe
        {
            Id = 6,
            Title = "Guacamole",
            Category = "Mexican",
            Description = "Fresh and chunky avocado dip with lime and cilantro.",
            Ingredients = new() { "Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt" },
            Steps = new()
            {
                "Halve avocados and remove pits.",
                "Mash avocado to desired consistency.",
                "Stir in diced onion, jalapeño, tomato, and cilantro.",
                "Add lime juice and salt to taste.",
                "Serve immediately with tortilla chips."
            },
            Ratings = new() { 4, 5, 4, 5, 5 }
        }
    };

    private int _nextId;

    public RecipeService()
    {
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int rating)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && rating >= 1 && rating <= 5)
        {
            recipe.Ratings.Add(rating);
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }
}

